SELECT 
FROM slow_sql
WHERE execute_time >= #{start} AND execute_time <= #{end}

    AND app_name = #{appName}


    AND cost_ms >= #{minCostMs}

ORDER BY cost_ms DESC
LIMIT #{limit}

SELECT 
FROM slow_sql
WHERE execute_time >= #{start} AND execute_time <= #{end}

    AND app_name = #{appName}


    AND cost_ms >= #{minCostMs}


    AND (execute_time < #{cursorTime}
         OR (execute_time = #{cursorTime} AND id < #{cursorId}))

ORDER BY execute_time DESC, id DESC
LIMIT #{limit}
